<?php
function e($value): string { return htmlspecialchars((string)($value ?? ''), ENT_QUOTES, 'UTF-8'); }
function redirect(string $url): never { header('Location: ' . $url); exit; }
function flash(string $type, string $message): void { $_SESSION['flash'][] = ['type'=>$type,'message'=>$message]; }
function csrf_token(): string { if (empty($_SESSION['_csrf'])) $_SESSION['_csrf'] = bin2hex(random_bytes(32)); return $_SESSION['_csrf']; }
function csrf_field(): string { return '<input type="hidden" name="_csrf" value="'.e(csrf_token()).'">'; }
function verify_csrf(): void { if ($_SERVER['REQUEST_METHOD']==='POST') { $sent=$_POST['_csrf']??''; if (!is_string($sent) || !hash_equals(csrf_token(),$sent)) { http_response_code(419); exit('Sesi formulir tidak valid. Muat ulang halaman lalu coba lagi.'); } } }
function require_login(): void { if (empty($_SESSION['user'])) { flash('warning','Silakan masuk terlebih dahulu.'); redirect('/sipeka/login.php'); } }
function require_role(string $role): void { if (($_SESSION['user']['role']??'') !== $role) { http_response_code(403); exit('403 — Anda tidak memiliki izin untuk membuka halaman ini.'); } }
function current_user(): array { return $_SESSION['user'] ?? []; }
function normalize_text(string $s): string { return preg_replace('/\s+/u',' ',trim($s)); }
function icon(string $name): string {
  if ($name === 'sun' || $name === 'moon') {
    $themePath = $name === 'sun'
      ? '<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M5 19l1.5-1.5M17.5 6.5L19 5"/>'
      : '<path d="M20.5 14.2A8.5 8.5 0 0 1 9.8 3.5 8.5 8.5 0 1 0 20.5 14.2Z"/>';
    return '<svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'.$themePath.'</svg>';
  }
  if ($name === 'eye' || $name === 'eye-off') {
    $eyePath = $name === 'eye'
      ? '<path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>'
      : '<path d="M3 3l18 18M10.6 10.6a2 2 0 0 0 2.8 2.8"/><path d="M9.9 5.2A10.8 10.8 0 0 1 12 5c6.4 0 10 7 10 7a15.8 15.8 0 0 1-3.1 3.9M6.2 6.2C3.5 8.1 2 12 2 12s3.6 7 10 7a10.6 10.6 0 0 0 3.2-.5"/>';
    return '<svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'.$eyePath.'</svg>';
  }
  $paths=['home'=>'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>','box'=>'<path d="m12 3 9 5-9 5-9-5z"/><path d="M3 8v9l9 5 9-5V8M12 13v9"/>','file'=>'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>','tag'=>'<path d="M20 13 11 22 2 13V2h11z"/><circle cx="7" cy="7" r="1"/>','map-pin'=>'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>','chart'=>'<path d="M3 3v18h18"/><path d="m7 14 4-4 4 3 5-7"/>','plus'=>'<path d="M12 5v14M5 12h14"/>','logout'=>'<path d="M10 17l5-5-5-5M15 12H3"/><path d="M12 3h7a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-7"/>','check'=>'<path d="m5 12 4 4L19 6"/>','clock'=>'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>','users'=>'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>'];
  return '<svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'.($paths[$name]??$paths['file']).'</svg>';
}
function badge_status(string $status): string { $map=['Menunggu Verifikasi'=>'wait','Terverifikasi'=>'verified','Sedang Ditangani'=>'handling','Selesai'=>'done','Ditolak'=>'rejected']; $cls=$map[$status]??'wait'; return '<span class="sp-badge status-'.e($cls).'"><span aria-hidden="true">●</span> '.e($status).'</span>'; }
function format_date($date): string { return $date ? date('d M Y, H:i',strtotime($date)) : '-'; }
function status_list(): array { return ['Menunggu Verifikasi','Terverifikasi','Sedang Ditangani','Selesai','Ditolak']; }
function upload_foto(array $file): string {
 if (($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK) throw new RuntimeException('Foto wajib diunggah.');
 if (($file['size']??0)>2*1024*1024) throw new RuntimeException('Ukuran foto maksimal 2 MB.');
 $ext=strtolower(pathinfo($file['name']??'',PATHINFO_EXTENSION)); if (!in_array($ext,['jpg','jpeg','png'],true)) throw new RuntimeException('Format foto harus JPG atau PNG.');
 $tmp=$file['tmp_name']??''; $finfo=new finfo(FILEINFO_MIME_TYPE); $mime=$finfo->file($tmp); $allowed=['image/jpeg'=>'jpg','image/png'=>'png'];
 if (!isset($allowed[$mime]) || !@getimagesize($tmp)) throw new RuntimeException('File yang diunggah bukan gambar JPG/PNG yang valid.');
 $name=bin2hex(random_bytes(16)).'.'.$allowed[$mime]; $dir=__DIR__.'/../uploads/laporan/'; if (!is_dir($dir)) mkdir($dir,0755,true);
 if (!move_uploaded_file($tmp,$dir.$name)) throw new RuntimeException('Foto gagal disimpan. Coba lagi.'); return $name;
}
function safe_unlink_photo(?string $name): void { if ($name && preg_match('/^[a-f0-9]{32}\.(jpg|png)$/',$name)) { $p=__DIR__.'/../uploads/laporan/'.$name; if (is_file($p)) @unlink($p); } }
function app_url(string $path=''): string { return '/sipeka/'.ltrim($path,'/'); }
function page_start(string $title, bool $public=false): void {
 $user=current_user(); $flashes=$_SESSION['flash']??[]; unset($_SESSION['flash']);
 echo '<!doctype html><html lang="id" data-bs-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><script>try{document.documentElement.setAttribute("data-bs-theme",localStorage.getItem("sipeka-theme")==="light"?"light":"dark")}catch(e){}</script><title>'.e($title).' · SIPEKA</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="'.app_url('assets/css/theme.css?v='.filemtime(__DIR__.'/../assets/css/theme.css')).'" rel="stylesheet"></head><body>';
 if ($public) { echo '<nav class="navbar navbar-expand-lg sp-public-nav"><div class="container-fluid sp-public-inner"><a class="navbar-brand sp-brand" href="'.app_url('').'"><img class="sp-brand-logo" src="'.app_url('assets/img/logo.png').'" alt=""> SIPEKA</a><button class="navbar-toggler" data-bs-toggle="collapse" data-bs-target="#publicNav" aria-label="Buka menu">☰</button><div class="collapse navbar-collapse sp-public-collapse" id="publicNav"><div class="navbar-nav sp-public-links"><a class="nav-link" href="'.app_url('').'">Beranda</a><a class="nav-link" href="'.app_url('#cara-kerja').'">Cara Kerja</a><a class="nav-link" href="'.app_url('#fitur').'">Fitur</a><a class="nav-link" href="'.app_url('#mulai').'">Mulai</a></div><div class="navbar-nav sp-public-actions"><a class="nav-link" href="'.app_url('login.php').'">Masuk</a><a class="btn sp-btn-primary btn-sm" href="'.app_url('register.php').'">Daftar</a><button type="button" class="sp-theme-toggle" data-theme-toggle aria-label="Ganti tema terang atau gelap">'.icon('sun').'</button></div></div></div></nav>'; }
 else { $role=$user['role']??'User'; $links=$role==='Admin'?[['admin/dashboard.php','chart','Dashboard'],['admin/inventaris.php','box','Inventaris'],['admin/laporan.php','file','Laporan'],['admin/lokasi.php','map-pin','Lokasi']]:[['user/dashboard.php','chart','Dashboard'],['user/buat-laporan.php','plus','Buat Laporan'],['user/laporan-saya.php','file','Laporan Saya']]; $waiting=0; if($role==='Admin'){try{global $pdo;$waiting=(int)$pdo->query("SELECT COUNT(*) FROM laporan WHERE status='Menunggu Verifikasi' AND deleted_at IS NULL")->fetchColumn();}catch(Throwable $e){}}
 echo '<div class="sp-app-shell"><aside class="sp-sidebar d-none d-lg-flex"><a class="sp-brand mb-4" href="'.app_url($role==='Admin'?'admin/dashboard.php':'user/dashboard.php').'"><img class="sp-brand-logo" src="'.app_url('assets/img/logo.png').'" alt=""><span>SIPEKA<small>SISTEM PENCATATAN DAN PELAPORAN FASILITAS KAMPUS</small></span></a><div class="sp-side-label">MENU UTAMA</div><nav class="sp-side-nav">'; foreach($links as [$href,$ico,$label]){ $active=str_contains($_SERVER['PHP_SELF']??'',$href)?' active':''; echo '<a class="sp-side-link'.$active.'" href="'.app_url($href).'">'.icon($ico).'<span>'.e($label).'</span>'; if($label==='Laporan'&&$waiting>0)echo '<span class="sp-count">'.$waiting.'</span>'; echo '</a>'; } echo '</nav><div class="sp-sidebar-bottom"><div class="sp-user-mini"><span class="sp-avatar">'.e(strtoupper(substr($user['nama']??'U',0,1))).'</span><span><strong>'.e($user['nama']??'Pengguna').'</strong><small>'.e($role).'</small></span></div><form method="post" action="'.app_url('logout.php').'">'.csrf_field().'<button class="sp-side-link sp-logout" type="submit">'.icon('logout').'<span>Keluar</span></button></form></div></aside><main class="sp-main"><header class="sp-topbar"><div class="d-flex align-items-center gap-3"><button class="btn sp-btn-outline d-lg-none" data-bs-toggle="offcanvas" data-bs-target="#mobileMenu" aria-label="Buka menu">☰</button><div><h1>'.e($title).'</h1><p>'.date('l, d F Y').'</p></div></div><div class="d-flex align-items-center gap-2"><span class="sp-avatar">'.e(strtoupper(substr($user['nama']??'U',0,1))).'</span></div></header><div class="offcanvas offcanvas-start sp-mobile-menu" tabindex="-1" id="mobileMenu"><div class="offcanvas-header"><div class="sp-brand"><img class="sp-brand-logo" src="'.app_url('assets/img/logo.png').'" alt=""> SIPEKA</div><button class="btn-close" data-bs-dismiss="offcanvas" aria-label="Tutup"></button></div><div class="offcanvas-body"><nav class="sp-side-nav">'; foreach($links as [$href,$ico,$label]) echo '<a class="sp-side-link" href="'.app_url($href).'">'.icon($ico).'<span>'.e($label).'</span></a>'; echo '</nav><form method="post" action="'.app_url('logout.php').'">'.csrf_field().'<button class="sp-side-link" type="submit">'.icon('logout').' Keluar</button></form></div></div><div class="sp-content">'; }
 foreach($flashes as $f){ $type=in_array($f['type'],['success','danger','warning','info'])?$f['type']:'info'; echo '<div class="toast show sp-toast align-items-center text-bg-'.e($type).' border-0 mb-3" role="status"><div class="d-flex"><div class="toast-body">'.e($f['message']).'</div><button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Tutup"></button></div></div>'; }
}
function page_end(bool $public=false): void { echo '</div>'; if(!$public)echo '</main></div>'; echo '<template id="sp-eye-icon">'.icon('eye').'</template><template id="sp-eye-off-icon">'.icon('eye-off').'</template><template id="sp-sun-icon">'.icon('sun').'</template><template id="sp-moon-icon">'.icon('moon').'</template><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="'.app_url('assets/js/app.js?v='.filemtime(__DIR__.'/../assets/js/app.js')).'"></script></body></html>'; }
function post_only(): void { if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Metode tidak diizinkan.');} verify_csrf(); }
function require_int($v,string $label,int $min=0): int { $n=filter_var($v,FILTER_VALIDATE_INT); if($n===false||$n<$min)throw new RuntimeException($label.' tidak valid.'); return $n; }
